META = dict(nama="Auto Transport", jp="自動車運送業", emoji="🚚", co="運送会社")
SPEC = dict(kerja="安全運転とお客様への責任を大切にしている", kerja_id="mengutamakan keselamatan berkendara dan tanggung jawab kepada pelanggan", soal={
 "shibou-01": ("なぜ運送の仕事を選びましたか。", "Mengapa Anda memilih pekerjaan transportasi?", "小さいころから、大きいトラックやバスが好きでした。人や荷物を安全に運ぶ仕事がしたいです。", "Sejak kecil saya suka truk dan bus besar. Saya ingin bekerja mengangkut orang dan barang dengan aman.", [("運送", "pengangkutan"), ("運転", "mengemudi"), ("荷物", "barang"), ("安全", "keselamatan")]),
 "shibou-02": ("なぜ日本で運転の仕事を学びたいですか。", "Mengapa Anda ingin belajar pekerjaan mengemudi di Jepang?", "日本の運転手は、時間と安全をとても大切にしていると聞きました。その考え方を学びたいです。", "Saya dengar pengemudi Jepang sangat mengutamakan ketepatan waktu dan keselamatan. Saya ingin belajar cara berpikir itu.", [("運転手", "pengemudi"), ("時間", "waktu"), ("考え方", "cara berpikir")]),
 "shibou-04": ("この仕事に興味を持った理由は何ですか。", "Apa alasan Anda tertarik pada pekerjaan ini?", "荷物がお客様に届いたとき、「ありがとう」と言われるのがうれしいと思いました。社会を支える仕事に、興味があります。", "Saya kira senang kalau barang sampai dan pelanggan berkata \"terima kasih\". Saya tertarik pada pekerjaan yang menopang masyarakat.", [("届ける", "mengantarkan"), ("社会", "masyarakat"), ("支える", "menopang")]),
 "shibou-05": ("運転の仕事で、一番楽しみなことは何ですか。", "Apa yang paling Anda nantikan dari pekerjaan mengemudi?", "日本のいろいろな道を、安全に運転できるようになることです。お客様に喜んでもらいたいです。", "Bisa mengemudi dengan aman di berbagai jalan Jepang. Saya ingin pelanggan merasa senang.", [("道", "jalan"), ("運転", "mengemudi"), ("喜ぶ", "senang")]),
 "shigoto-01": ("自動車運送の主な仕事は何だと思いますか。", "Menurut Anda, apa pekerjaan utama transportasi kendaraan?", "トラックで荷物を運んだり、バスやタクシーでお客様を運んだりする仕事だと思います。", "Saya kira pekerjaannya mengangkut barang dengan truk, atau mengangkut penumpang dengan bus dan taksi.", [("トラック", "truk"), ("バス", "bus"), ("お客様", "penumpang/pelanggan")]),
 "shigoto-02": ("朝早くや、夜遅くに働くことはできますか。", "Bisakah Anda bekerja sangat pagi atau larut malam?", "はい、できます。仕事の前は、しっかり寝て、体調を整えます。", "Ya, bisa. Sebelum bekerja saya tidur cukup dan menjaga kondisi badan.", [("早朝", "pagi buta"), ("深夜", "tengah malam"), ("体調を整える", "menjaga kondisi")]),
 "shigoto-03": ("長い時間、座って運転できますか。", "Bisakah Anda mengemudi sambil duduk dalam waktu lama?", "はい、できます。決まった休けいを取って、ときどき体を動かします。", "Ya, bisa. Saya mengambil istirahat yang ditentukan dan sesekali menggerakkan badan.", [("休けい", "istirahat"), ("座る", "duduk"), ("体を動かす", "menggerakkan badan")]),
 "shigoto-04": ("雨や雪の日の運転について、どう思いますか。", "Bagaimana pendapat Anda tentang mengemudi saat hujan atau salju?", "道がすべりやすいので、とても注意が必要です。スピードを出さないで、ゆっくり運転します。", "Karena jalan licin, perlu sangat berhati-hati. Saya tidak ngebut dan mengemudi pelan.", [("雪", "salju"), ("すべる", "licin"), ("スピード", "kecepatan")]),
 "shigoto-05": ("荷物を持ったり、運んだりする体力はありますか。", "Apakah Anda punya stamina untuk mengangkat dan memindahkan barang?", "はい、あります。毎日運動をして、体力をつけています。重い荷物は、腰に気をつけて持ちます。", "Ya, ada. Saya berolahraga setiap hari. Barang berat saya angkat dengan menjaga pinggang.", [("体力", "stamina"), ("重い", "berat"), ("腰", "pinggang")]),
 "shigoto-06": ("忙しい時期や、帰りが遅い日があっても大丈夫ですか。", "Apakah Anda baik-baik saja dengan musim sibuk dan hari pulang larut?", "はい、大丈夫です。ただ、決められた休けいや休みは、必ず守ります。", "Ya, tidak masalah. Namun saya pasti mematuhi istirahat dan libur yang ditentukan.", [("繁忙期", "musim sibuk"), ("帰り", "pulang"), ("休み", "libur")]),
 "shigoto-07": ("車に乗る前に、何を確認しますか。", "Apa yang Anda periksa sebelum menaiki kendaraan?", "タイヤ、ライト、ブレーキ、ミラーなどを確認します。問題があったら、すぐに責任者に伝えます。", "Saya memeriksa ban, lampu, rem, dan kaca spion. Kalau ada masalah, segera saya sampaikan kepada penanggung jawab.", [("点検", "pemeriksaan"), ("ブレーキ", "rem"), ("ミラー", "spion")]),
 "shigoto-08": ("知らない道を運転するとき、どうしますか。", "Apa yang Anda lakukan saat mengemudi di jalan yang tidak dikenal?", "出発する前に、地図やナビで道を確認します。分からなくなったら、安全な場所で止まって、会社に連絡します。", "Sebelum berangkat saya memeriksa rute dengan peta atau navigasi. Kalau bingung, saya berhenti di tempat aman dan menghubungi perusahaan.", [("ナビ", "navigasi"), ("地図", "peta"), ("連絡", "menghubungi")]),
 "shigoto-09": ("運転の仕事で、大切なことは何だと思いますか。", "Menurut Anda, apa yang penting dalam pekerjaan mengemudi?", "安全に、約束の時間を守ることだと思います。交通ルールを守って、あわてずに運転します。", "Menurut saya, mengemudi dengan aman dan tepat waktu. Saya menaati aturan lalu lintas dan mengemudi tanpa tergesa-gesa.", [("交通ルール", "aturan lalu lintas"), ("時間を守る", "tepat waktu"), ("あわてる", "tergesa-gesa")]),
 "shigoto-10": ("荷物を届けるまで、どんな作業がありますか。", "Pekerjaan apa saja sampai barang diantar?", "荷物を積んで、運転して、届け先で降ろします。受け取りのサインをもらって、会社に報告します。", "Memuat barang, mengemudi, lalu menurunkannya di tujuan. Mendapatkan tanda tangan penerimaan lalu melapor ke perusahaan.", [("積む", "memuat"), ("降ろす", "menurunkan"), ("受け取り", "penerimaan")]),
 "shigoto-11": ("お客様や、届け先の人と話すとき、何に気をつけますか。", "Apa yang Anda perhatikan saat berbicara dengan pelanggan atau penerima barang?", "元気にあいさつをして、ていねいな言葉で話します。荷物は、両手でていねいに渡します。", "Saya menyapa dengan semangat dan berbicara sopan. Barang saya serahkan dengan dua tangan dengan hati-hati.", [("あいさつ", "salam"), ("ていねい", "sopan"), ("渡す", "menyerahkan")]),
 "shigoto-12": ("運転日報や、記録を書くことはできますか。", "Apakah Anda bisa menulis laporan harian dan catatan mengemudi?", "はい、できます。走った時間や、休けいの時間を、毎日正しく書きます。", "Ya, bisa. Saya menulis waktu perjalanan dan waktu istirahat dengan benar setiap hari.", [("日報", "laporan harian"), ("記録", "catatan"), ("正しく", "dengan benar")]),
 "shigoto-13": ("日本の運転免許について、知っていることはありますか。", "Apa yang Anda ketahui tentang SIM di Jepang?", "運転するためには、日本の免許が必要だと聞いています。会社の人に、取り方を教えてもらいたいです。", "Saya dengar untuk mengemudi dibutuhkan SIM Jepang. Saya ingin diajari cara mendapatkannya oleh orang perusahaan.", [("免許", "SIM"), ("取る", "mendapatkan"), ("教えてもらう", "diajari")]),
 "taiou-02": ("荷物を壊してしまったら、どうしますか。", "Apa yang Anda lakukan kalau merusak barang kiriman?", "すぐに正直に会社に報告します。お客様にも、ていねいに謝って、会社の指示に従います。", "Saya segera melapor jujur kepada perusahaan. Saya juga meminta maaf dengan sopan kepada pelanggan dan mengikuti instruksi perusahaan.", [("壊す", "merusak"), ("謝る", "meminta maaf"), ("報告", "melapor")]),
 "taiou-06": ("道が工事や事故で、通れなくなったら、どうしますか。", "Apa yang Anda lakukan kalau jalan tidak bisa dilalui karena perbaikan atau kecelakaan?", "安全な場所に止まって、会社に連絡します。会社の指示を聞いて、別の道を行きます。", "Saya berhenti di tempat aman dan menghubungi perusahaan. Saya mendengar instruksi perusahaan dan memakai jalan lain.", [("工事", "perbaikan jalan"), ("事故", "kecelakaan"), ("別の道", "jalan lain")]),
 "taiou-08": ("約束の時間に間に合わなくなりそうなとき、どうしますか。", "Apa yang Anda lakukan kalau sepertinya tidak sempat tiba tepat waktu?", "あせらないで、すぐに会社に連絡します。スピードを出さないで、安全に運転します。", "Saya tidak panik dan segera menghubungi perusahaan. Saya tidak ngebut dan tetap mengemudi dengan aman.", [("間に合う", "sempat"), ("あせる", "panik"), ("連絡", "menghubungi")]),
 "taiou-11": ("長い運転で、疲れたり、眠くなったりしたら、どうしますか。", "Apa yang Anda lakukan kalau lelah atau mengantuk saat mengemudi jauh?", "無理をしないで、安全な場所で車を止めて、休みます。眠いまま運転はしません。", "Saya tidak memaksakan diri, berhenti di tempat aman, dan beristirahat. Saya tidak mengemudi dalam keadaan mengantuk.", [("眠い", "mengantuk"), ("休む", "istirahat"), ("無理", "memaksakan")]),
 "taiou-12": ("お客様に、日本語が分からなくて、聞き返されたら、どうしますか。", "Apa yang Anda lakukan kalau pelanggan menanyakan ulang karena bahasa Jepang Anda kurang jelas?", "ゆっくり、もう一度言います。それでも分からないときは、会社の人に代わってもらいます。", "Saya mengulang dengan pelan. Kalau tetap tidak paham, saya minta orang perusahaan menggantikan.", [("聞き返す", "bertanya ulang"), ("ゆっくり", "pelan"), ("代わる", "menggantikan")]),
 "tim-01": ("荷物の積み下ろしのとき、チームの人と、どのように作業しますか。", "Saat memuat dan membongkar barang, bagaimana Anda bekerja dengan tim?", "声をかけ合って、順番に作業します。重い荷物は、二人で運びます。", "Kami saling memberi aba-aba dan bekerja bergantian. Barang berat dibawa berdua.", [("積み下ろし", "bongkar muat"), ("声をかけ合う", "saling memberi aba-aba"), ("順番", "bergantian")]),
 "tim-02": ("配車の担当者の指示が分からなかったとき、どうしますか。", "Apa yang Anda lakukan kalau tidak paham instruksi petugas penjadwalan kendaraan?", "出発する前に、「もう一度お願いします」と聞きます。分からないまま出発しないようにします。", "Sebelum berangkat saya meminta \"Tolong ulangi\". Saya tidak berangkat dalam keadaan tidak paham.", [("配車", "penjadwalan kendaraan"), ("指示", "instruksi"), ("出発", "berangkat")]),
 "tim-03": ("運転中に、会社と、どのように連絡をとりますか。", "Bagaimana Anda berkomunikasi dengan perusahaan saat mengemudi?", "運転中は、電話を使いません。安全な場所に止まってから、連絡します。", "Saat mengemudi, saya tidak memakai telepon. Saya berhenti di tempat aman lalu menghubungi.", [("連絡", "menghubungi"), ("運転中", "saat mengemudi"), ("止まる", "berhenti")]),
 "tim-04": ("会社の運転手の仲間と、どのように仲良くなりたいですか。", "Bagaimana Anda ingin akrab dengan sesama pengemudi di perusahaan?", "毎日、元気にあいさつをします。道や運転のコツを教えてもらったときは、「ありがとうございます」と言います。", "Setiap hari saya menyapa dengan semangat. Saat diberi tips jalan atau mengemudi, saya mengatakan \"Terima kasih\".", [("あいさつ", "salam"), ("コツ", "trik"), ("仲間", "rekan")]),
 "anzen-01": ("運転するとき、必ず守ることは何ですか。", "Apa yang wajib dipatuhi saat mengemudi?", "交通ルールとスピードを守ります。シートベルトを必ず着けます。お酒を飲んだら、絶対に運転しません。", "Saya menaati aturan lalu lintas dan batas kecepatan. Saya selalu memakai sabuk pengaman. Kalau minum alkohol, saya sama sekali tidak mengemudi.", [("シートベルト", "sabuk pengaman"), ("飲酒運転", "mengemudi sambil mabuk"), ("スピード", "kecepatan")]),
 "anzen-02": ("バックするとき、何に気をつけますか。", "Apa yang Anda perhatikan saat memundurkan kendaraan?", "ミラーとカメラをよく見ます。まわりに人がいないか、車から降りて確認するときもあります。", "Saya melihat spion dan kamera dengan teliti. Kadang saya turun untuk memastikan tidak ada orang di sekitar.", [("バック", "mundur"), ("死角", "titik buta"), ("確認", "memastikan")]),
 "anzen-03": ("荷物を積むとき、何に気をつけますか。", "Apa yang Anda perhatikan saat memuat barang?", "決められた重さを超えないようにします。荷物が動かないように、しっかり固定します。", "Saya tidak melebihi berat yang ditentukan. Saya mengikat barang dengan kuat agar tidak bergeser.", [("重さ", "berat"), ("固定", "mengikat/mengunci"), ("積む", "memuat")]),
 "anzen-04": ("事故を起こしそうになったら、どうしますか。", "Apa yang Anda lakukan kalau hampir terjadi kecelakaan?", "安全な場所に止まって、落ち着きます。そのあと、会社に報告します。小さいことでも、必ず報告します。", "Saya berhenti di tempat aman dan menenangkan diri. Setelah itu saya melapor ke perusahaan. Sekecil apa pun, saya pasti melapor.", [("ヒヤリハット", "nyaris celaka"), ("報告", "melapor"), ("落ち着く", "tenang")]),
 "seikatsu-07": ("車が多い町や、雪の多い地域での生活に、不便なことがあっても大丈夫ですか。", "Apakah Anda baik-baik saja dengan ketidaknyamanan hidup di kota padat kendaraan atau daerah bersalju?", "大丈夫です。天気予報をよく見て、準備をします。雪の日の運転や歩き方も、勉強します。", "Tidak masalah. Saya akan sering melihat prakiraan cuaca dan bersiap. Saya juga akan belajar cara mengemudi dan berjalan di hari bersalju.", [("天気予報", "prakiraan cuaca"), ("準備", "persiapan"), ("雪", "salju")]),
 "seikatsu-08": ("日本の道路や、交通のルールについて、知っていることはありますか。", "Apa yang Anda ketahui tentang jalan dan aturan lalu lintas di Jepang?", "日本では、車は左側を走ると聞きました。信号や標識を、しっかり守る国だと思います。", "Saya dengar di Jepang kendaraan melaju di sisi kiri. Menurut saya Jepang negara yang sangat menaati lampu lalu lintas dan rambu.", [("左側", "sisi kiri"), ("標識", "rambu"), ("信号", "lampu lalu lintas")]),
 "mokuhyou-05": ("日本で運送の仕事を学んだあと、自分の国でどんなことをしたいですか。", "Setelah belajar pekerjaan transportasi di Jepang, apa yang ingin Anda lakukan di negara sendiri?", "日本で学んだ安全運転と、時間を守る習慣を使って、自分の国でも運転の仕事をしたいです。", "Saya ingin bekerja sebagai pengemudi di negara saya dengan memakai kebiasaan mengemudi aman dan tepat waktu yang saya pelajari di Jepang.", [("安全運転", "mengemudi aman"), ("習慣", "kebiasaan"), ("運転", "mengemudi")]),
})
